 state=newState()
 var users []UserModel;var themes []ThemeModel;var streams []LivestreamModel;var tags []TagModel;var st []LivestreamTagModel;var comments []LivecommentModel;var reactions []ReactionModel;var words []NGWord
 for _,q:=range []struct{dest interface{};table string}{{&users,"users"},{&themes,"themes"},{&streams,"livestreams"},{&tags,"tags"},{&st,"livestream_tags"},{&comments,"livecomments"},{&reactions,"reactions"},{&words,"ng_words"},{&state.Slots,"reservation_slots"}} {if err:=dbConn.Select(q.dest,"SELECT * FROM "+q.table+" ORDER BY id");err!=nil{return err}}
 for _,u:=range users {state.Users[u.ID]=u;bump("user",u.ID)};for _,t:=range themes {state.Themes[t.UserID]=Theme{ID:t.ID,DarkMode:t.DarkMode};bump("theme",t.ID)}
 for _,s:=range streams {state.Streams[s.ID]=s;bump("stream",s.ID)};for _,t:=range tags {state.Tags[t.ID]=Tag{ID:t.ID,Name:t.Name}};for _,t:=range st {state.StreamTags[t.LivestreamID]=append(state.StreamTags[t.LivestreamID],t.TagID)}
 for _,c:=range comments {state.Comments[c.ID]=c;bump("comment",c.ID)};for _,r:=range reactions {state.Reactions[r.ID]=r;bump("reaction",r.ID)};for _,w:=range words {state.Words[w.ID]=w;bump("word",w.ID)}
 rebuild();if err:=snapshot();err!=nil{return err};if journal!=nil{journal.Close()};var err error;journal,err=os.OpenFile(filepath.Join(dataDir,"journal.jsonl"),os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0644);return err
}
