package main

import (
 "bufio"
 "encoding/json"
 "time"
 "github.com/labstack/echo/v4"
)
type walTicket struct {done chan struct{};err error}
type walJob struct {data []byte;ticket *walTicket}
var walQueue=make(chan walJob,1024)
var walStarted bool
var latestTicket *walTicket
func startWAL(){walStarted=true;go func(){for first:=range walQueue{
 jobs:=[]walJob{first}
 timer:=time.NewTimer(150*time.Microsecond)
collect:
 for len(jobs)<256 {select{case j:=<-walQueue:jobs=append(jobs,j);case <-timer.C:break collect}}
 if !timer.Stop(){select{case <-timer.C:default:}}
 w:=bufio.NewWriterSize(journal,256*1024);var err error
 for _,j:=range jobs{if err==nil&&len(j.data)>0{_,err=w.Write(j.data)}}
 if err==nil{err=w.Flush()};if err==nil{err=journal.Sync()}
 for _,j:=range jobs{j.ticket.err=err;close(j.ticket.done)}
 }}()}
func flushWAL()error{if !walStarted{return nil};t:=&walTicket{done:make(chan struct{})};walQueue<-walJob{ticket:t};<-t.done;return t.err}
func commit(e Event)error {
 b,err:=json.Marshal(e);if err!=nil{return err};b=append(b,'\n')
 t:=&walTicket{done:make(chan struct{})};walQueue<-walJob{data:b,ticket:t};latestTicket=t;apply(e);return nil
}
type pendingResponse struct {code int;value interface{};blob []byte;contentType string;ticket *walTicket}
func reply(c echo.Context,code int,value interface{})error {c.Set("pendingResponse",pendingResponse{code:code,value:value,ticket:latestTicket});return nil}
func replyBlob(c echo.Context,code int,contentType string,b []byte)error {c.Set("pendingResponse",pendingResponse{code:code,blob:b,contentType:contentType,ticket:latestTicket});return nil}
func deferredResponse(next echo.HandlerFunc)echo.HandlerFunc{return func(c echo.Context)error {
 if err:=next(c);err!=nil{return err};v,ok:=c.Get("pendingResponse").(pendingResponse);if !ok{return nil}
 if v.ticket!=nil{<-v.ticket.done;if v.ticket.err!=nil{return v.ticket.err}}
 if v.contentType!=""{return c.Blob(v.code,v.contentType,v.blob)};if v.value==nil{return c.NoContent(v.code)};return c.JSON(v.code,v.value)
}}
// Keep the log compatible with the original event decoder while omitting unrelated fields.
func(e Event)MarshalJSON()([]byte,error){m:=map[string]interface{}{"Kind":e.Kind};switch e.Kind {
 case "user":m["User"]=e.User;m["Theme"]=e.Theme
 case "icon":m["ID"]=e.ID;m["UserID"]=e.UserID;m["Image"]=e.Image
 case "stream":m["Stream"]=e.Stream;m["Tags"]=e.Tags
 case "comment":m["Comment"]=e.Comment
 case "reaction":m["Reaction"]=e.Reaction
 case "report":m["Report"]=e.Report
 case "word":m["Word"]=e.Word
 case "enter","exit":m["Viewer"]=e.Viewer
 };return json.Marshal(m)}
EOF
