package main
import("encoding/binary";_ "embed";"strings";"sync")
// generalCIWeights was measured from the competition MySQL server's utf8mb4_general_ci collation.
//go:embed general-ci.bin
var generalCIWeights []byte
var matchCache sync.Map
type likePattern struct{plain string;wild bool;tokens []int32}
func collationWeight(r rune)rune {if r>=65536{return 0xfffd};return rune(binary.BigEndian.Uint16(generalCIWeights[int(r)*2:]))}
