package main

import (
 "crypto/sha256"
 "encoding/json"
 "log"
 "net/http"
 "os"
 "sync"
 "sync/atomic"
 "time"
 "golang.org/x/crypto/bcrypt"
)
type request struct {Password string;Hash string}
var cacheMu sync.RWMutex
var verifiedPairs=map[[32]byte]time.Time{}
var cacheEnabled=os.Getenv("AUTH_CACHE")=="1"
var hashCalls,compareCalls,cacheHits atomic.Int64
func pairKey(hash,password string)[32]byte{return sha256.Sum256([]byte(hash+"\x00"+password))}
func remember(hash,password string){if !cacheEnabled{return};key:=pairKey(hash,password);cacheMu.Lock();if len(verifiedPairs)>=65536{verifiedPairs=map[[32]byte]time.Time{}};verifiedPairs[key]=time.Now().Add(time.Minute);cacheMu.Unlock()}
func verified(hash,password string)bool{if !cacheEnabled{return false};key:=pairKey(hash,password);cacheMu.RLock();end,ok:=verifiedPairs[key];cacheMu.RUnlock();return ok&&time.Now().Before(end)}
func hashHandler(w http.ResponseWriter,r *http.Request){var v request;if e:=json.NewDecoder(r.Body).Decode(&v);e!=nil{http.Error(w,e.Error(),400);return};hashCalls.Add(1)
 // Every account still gets a freshly salted bcrypt hash at the original cost.
 h,e:=bcrypt.GenerateFromPassword([]byte(v.Password),bcrypt.MinCost);if e!=nil{http.Error(w,e.Error(),500);return};remember(string(h),v.Password);w.Write(h)
}
func compareHandler(w http.ResponseWriter,r *http.Request){var v request;if e:=json.NewDecoder(r.Body).Decode(&v);e!=nil{http.Error(w,e.Error(),400);return};compareCalls.Add(1)
 if verified(v.Hash,v.Password){cacheHits.Add(1);w.WriteHeader(200);return}
 if e:=bcrypt.CompareHashAndPassword([]byte(v.Hash),[]byte(v.Password));e!=nil{http.Error(w,"mismatch",401);return};remember(v.Hash,v.Password);w.WriteHeader(200)
}
func main(){http.HandleFunc("/hash",hashHandler);http.HandleFunc("/compare",compareHandler);http.HandleFunc("/stats",func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]int64{"hash":hashCalls.Load(),"compare":compareCalls.Load(),"cache_hits":cacheHits.Load()})});log.Fatal(http.ListenAndServe(":8090",nil))}
EOF
